@@ -0,0 +1,13 @@
+// The audit log: one entry per authenticated request that may change data.
+
+/** Appends an audit entry; `at` is an ISO instant from the caller. */
+export function recordAudit(store, { at, key, method, path, status }) {
+  const entry = { id: store.nextId("audit"), at, key, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...store.data.audit].reverse();
+}
