+// API keys and roles. Roles are ordered: viewer < cook < manager.
+import { AppError } from "../errors.js";
+
+const RANK = { viewer: 0, cook: 1, manager: 2 };
+
+// Writes a cook may do besides reading: cook, waste, temperatures, stock-take counts.
+const COOK_WRITES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** The lowest role allowed to make this request. */
+export function requiredRole(method, pathname) {
+  if (method === "GET") return pathname === "/audit" ? "manager" : "viewer";
+  return COOK_WRITES.some(([m, re]) => m === method && re.test(pathname)) ? "cook" : "manager";
+}
+
+/** The key record for the request's Bearer token, or throws `unauthorized`. */
+export function authenticate(store, headers) {
+  const name = Object.keys(headers).find((h) => h.toLowerCase() === "authorization");
+  const m = name && /^Bearer\s+(\S+)$/i.exec(String(headers[name]));
+  const found = m && store.data.apiKeys.find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws `forbidden` unless the key's role may make this request. */
+export function authorize(apiKey, method, pathname) {
+  if (RANK[apiKey.role] === undefined || RANK[apiKey.role] < RANK[requiredRole(method, pathname)])
+    throw new AppError("forbidden", { role: apiKey.role, method, path: pathname });
+}
